<template>
  <div class="roster-page">
    <section class="roster-panel">
      <header class="roster-header"><div><div class="eyebrow">人事专区 · 周排班</div><h2>员工周排班 <el-tag :type="week.status==='published'?'success':'info'" size="small">{{ week.status==='published'?'已固定':'草稿' }}</el-tag></h2><p>安排每周工作与休息，点击姓名查看个人存假。</p></div><div class="header-actions"><span v-if="dirty" class="unsaved-dot">有未保存修改</span><el-button v-if="week.can_submit" :loading="saving" :disabled="loading" @click="save(false)">保存草稿</el-button><el-button v-if="week.can_submit && week.status!=='published'" type="primary" :loading="saving" :disabled="loading" @click="save(true)">提交本周</el-button></div></header>
      <div class="roster-filters"><div class="scope-controls"><span v-if="context.own_only" class="store-label">{{ context.scopes[0]?.label }}</span><template v-else><el-radio-group v-model="scopeType" @change="changeScope"><el-radio-button value="store">门店员工</el-radio-button><el-radio-button value="office">办公室员工</el-radio-button></el-radio-group><StoreRegionSelect v-if="scopeType==='store'" v-model="storeId" :stores="stores" :clearable="false" input-width="240px" @update:model-value="changeScope" /></template></div><div class="week-controls"><el-button aria-label="上一周" :icon="ArrowLeft" @click="moveWeek(-7)" /><el-date-picker v-model="pickedDate" type="date" value-format="YYYY-MM-DD" :clearable="false" style="width:150px" @change="changeWeek" /><el-button aria-label="下一周" :icon="ArrowRight" @click="moveWeek(7)" /><el-button text @click="thisWeek">本周</el-button></div></div>
      <div class="week-caption"><div><b>{{ week.week_start }} — {{ week.dates?.[6] }}</b><span>{{ week.employees?.length || 0 }} 位员工</span></div><div class="legend-list"><span v-for="item in [...shiftOptions,{value:'unassigned',label:'待排班'}]" :key="item.value" class="legend-item"><i :class="item.value" />{{ item.label }}</span></div></div>
      <div class="roster-scroll" v-loading="loading"><table class="roster-table"><thead><tr><th>员工 <small>点击姓名查看存假</small></th><th v-for="date in week.dates" :key="date" :class="{'today-column':date===context.today}"><span class="weekday">{{ weekdays[new Date(date+'T12:00:00+08:00').getUTCDay()] }}</span><b class="date-number">{{ date.slice(5).replace('-',' / ') }}</b><span v-if="date===context.today" class="today-badge">今天</span></th></tr></thead><tbody><tr v-for="person in week.employees" :key="person.employee_id"><th><button class="employee-name" @click="openBalance(person)"><span class="employee-avatar">{{ person.name.slice(-1) }}</span><span><b>{{ person.name }}</b><small>{{ person.hire_type }}</small></span></button></th><td v-for="day in person.days" :key="day.date" :class="{'today-column':day.date===context.today}"><button :aria-label="`${person.name} ${day.date} ${label(day)}`" :title="day.readonly_reason || '点击安排班次'" :class="['shift-cell',color(day),{'readonly-cell':!day.can_edit}]" @click="openDay(person,day)"><span class="shift-state"><el-icon v-if="color(day)==='unassigned'"><Plus /></el-icon><b>{{ label(day) }}</b></span><span v-if="day.attendance?.punch_count" class="punch-summary"><span>打卡 {{ punchClock(day.attendance.start_time,day.date) }} — {{ punchClock(day.attendance.end_time,day.date) }}</span><span>{{ day.attendance.hours===null?'工时待核':`${day.attendance.incomplete?'已配对 ':''}${day.attendance.hours} 小时` }}<em v-if="day.attendance.incomplete"> · 缺卡待核</em></span></span><el-icon v-if="!day.can_edit" class="cell-lock"><Lock /></el-icon></button></td></tr><tr v-if="!week.employees?.length"><td colspan="8" class="empty">请选择门店，开始安排员工本周班次</td></tr></tbody></table></div>
      <footer class="roster-footer"><span><el-icon><InfoFilled /></el-icon>休息用当月额度 · 调休用个人存假</span><span>{{ context.can_confirm?'人事可补排或调整本月日期；历史月份只可查看。':'本月空白日期可补排；已过去日期的原有安排请联系人事修改。' }}</span></footer>
    </section>
    <el-dialog v-model="dayVisible" class="roster-day-dialog" title="安排班次" width="min(540px,calc(100vw - 32px))" align-center :close-on-click-modal="false">
      <template v-if="selectedDay"><div class="dialog-person"><span class="employee-avatar large">{{ selectedPerson.name.slice(-1) }}</span><div><h3>{{ selectedPerson.name }}<span>{{ selectedPerson.hire_type }}</span></h3><p>{{ selectedDay.date }} · {{ weekdays[new Date(selectedDay.date+'T12:00:00+08:00').getUTCDay()] }}</p></div><span class="current-state">当前：{{ label(selectedDay) }}</span></div>
        <el-alert v-if="!selectedDay.can_edit" :title="selectedDay.readonly_reason || '此日期只可查看'" type="info" :closable="false" show-icon class="readonly-notice" />
        <p class="field-label">选择当天安排</p><div class="shift-options"><button v-for="option in shiftOptions" :key="option.value" type="button" :class="['shift-option',option.value,{'selected':dayForm.type===option.value}]" :aria-pressed="dayForm.type===option.value" :disabled="optionDisabled(option)" @click="selectShift(option)"><span class="option-heading"><el-icon><component :is="option.icon" /></el-icon><b>{{ option.label }}</b><el-icon v-if="dayForm.type===option.value" class="selected-check"><CircleCheckFilled /></el-icon></span><small>{{ option.description }}</small></button></div>
        <div v-if="scope==='office'" class="dialog-note">办公室的正常工作、休息日期由人事月历统一设置。</div>
        <div v-if="dayForm.type==='leave'" class="leave-note"><label class="field-label" for="roster-leave-reason">请假备注 <span>*</span></label><el-input id="roster-leave-reason" v-model="dayForm.reason" type="textarea" :rows="3" :disabled="!selectedDay.can_edit" placeholder="例如：身体不适、处理个人事务" maxlength="500" /><p v-if="dayError" class="field-error" role="alert">{{ dayError }}</p></div>
      </template><template #footer><div class="dialog-actions"><span v-if="selectedDay?.can_edit">确定后记入草稿，保存后生效</span><el-button @click="dayVisible=false">{{ selectedDay?.can_edit?'取消':'关闭' }}</el-button><el-button v-if="selectedDay?.can_edit" type="primary" :disabled="!shiftOptions.some(option=>option.value===dayForm.type)" @click="applyDay">确定安排</el-button></div></template>
    </el-dialog>
    <el-dialog v-model="balanceVisible" :title="`${balancePerson?.name || ''} · 假期库存`" width="min(850px,96vw)">
      <div v-loading="balanceLoading"><el-alert v-if="balanceError" :title="balanceError" type="error" :closable="false" /><template v-if="account"><div class="balance-summary"><div><small>个人存假可用</small><b>{{ account.balance }} 天</b></div><div><small>本月正常休息剩余</small><b>{{ normalRestRemaining }} 天</b></div><div><small>本月已使用存假</small><b>{{ currentMonth?.used || 0 }} 天</b></div></div><p class="hint">截至 {{ account.as_of }}；{{ account.active_from }} 起启用库存。选择休息使用当月正常休息额度；选择调休直接扣最早到期的个人存假。每笔三个月有效，12 月 31 日结束清空。{{ account.employee.hire_type==='兼职'?'兼职按实际工时计薪，暂不存假。':'' }}</p><h4>存假批次</h4><el-table :data="account.lots" size="small" max-height="200" empty-text="暂无存假"><el-table-column prop="date" label="产生日期" /><el-table-column prop="amount" label="存入天数" /><el-table-column prop="remaining" label="剩余天数" /><el-table-column label="到期日（当日不可用）"><template #default="{row}"><span :class="{'expiring':row.remaining>0 && row.expires_on<=soon}">{{ row.expires_on }}{{ row.remaining>0 && row.expires_on<=soon?' · 即将到期':'' }}</span></template></el-table-column></el-table><h4>库存流水</h4><el-table :data="[...account.events].reverse()" size="small" max-height="220" empty-text="暂无流水"><el-table-column prop="date" label="日期" /><el-table-column label="类型"><template #default="{row}">{{ eventLabels[row.type] }}</template></el-table-column><el-table-column label="天数"><template #default="{row}">{{ row.type==='earn'?'+':'−' }}{{ row.amount }}</template></el-table-column><el-table-column prop="source_date" label="存假来源日期" /></el-table><el-collapse><el-collapse-item title="核算修订记录"><el-table :data="revisions" size="small"><el-table-column prop="version" label="版本" /><el-table-column prop="source" label="原因" /><el-table-column prop="created_at" label="时间" /></el-table></el-collapse-item></el-collapse></template></div>
    </el-dialog>
  </div>
</template>
<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {ArrowLeft,ArrowRight,Plus,Lock,InfoFilled,Check,Clock,Document,CoffeeCup,CircleCheckFilled} from '@element-plus/icons-vue'
import StoreRegionSelect from '@/components/StoreRegionSelect.vue'
import {getRosterContext,getRosterWeek,saveRosterWeek,getRosterBalance} from '@/api'
const context=ref({scopes:[],own_only:false}),scope=ref(''),scopeType=ref('store'),storeId=ref(null),pickedDate=ref(''),week=ref({employees:[],dates:[]}),loading=ref(false),saving=ref(false)
const baseline=ref('')
const planSnapshot=()=>JSON.stringify((week.value.employees || []).map(person=>({id:person.employee_id,days:person.days.map(day=>Object.fromEntries(['date','type','start_time','end_time','next_day','reason'].map(key=>[key,day[key]])))})))
const dirty=computed(()=>!!baseline.value && planSnapshot()!==baseline.value)
const dayVisible=ref(false),selectedPerson=ref(null),selectedDay=ref(null),dayForm=reactive({}),dayError=ref('')
const balanceVisible=ref(false),balanceLoading=ref(false),balancePerson=ref(null),account=ref(null),revisions=ref([]),balanceError=ref('')
const weekdays=['周日','周一','周二','周三','周四','周五','周六'],eventLabels={earn:'超额出勤存假',use:'调休扣减',expire:'三个月到期清除',year_clear:'年底清零'}
const stores=computed(()=>context.value.scopes.filter(s=>s.value.startsWith('store:')).map(s=>({id:Number(s.value.split(':')[1]),store_name:s.label})))
const currentMonth=computed(()=>account.value?.months.find(m=>m.period===account.value.as_of.slice(0,7)))
const normalRestRemaining=computed(()=>Math.max(0,(currentMonth.value?.rest_allowance || 0)-(currentMonth.value?.normal_rest_used || 0)))
const add=(date,days)=>{const d=new Date(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}
const monday=date=>add(date,-((new Date(date+'T00:00:00Z').getUTCDay()+6)%7))
const soon=computed(()=>account.value?add(account.value.as_of,7):'')
const shiftOptions=[{value:'work',label:'出勤',description:'按门店默认班次出勤',icon:Check},{value:'rest',label:'休息',description:'使用本月正常休息额度',icon:CoffeeCup},{value:'leave',label:'请假',description:'填写原因，登记请假',icon:Document},{value:'comp',label:'调休',description:'使用个人存假余额',icon:Clock}]
const punchClock=(time,date)=>!time?'未打卡':time.slice(0,10)===date?time.slice(11,16):`${time.slice(5,10).replace('-','/')} ${time.slice(11,16)}`
const color=day=>day.type==='work' && day.actual?.banked>0?'overtime':day.type==='holiday'?'rest':day.type || 'unassigned'
const label=day=>({work:'出勤',rest:'休息',leave:'请假',comp:'调休',overtime:'加班存假',holiday:'休息',unassigned:'待排班'})[color(day)] || '待排班'
let loadGeneration=0,balanceGeneration=0
async function load(){if(!scope.value || !pickedDate.value)return;const generation=++loadGeneration;loading.value=true;try{const data=await getRosterWeek({scope:scope.value,week_start:monday(pickedDate.value)});if(generation===loadGeneration){week.value=data.week;baseline.value=planSnapshot()}}catch(error){ElMessage.error(error.message)}finally{if(generation===loadGeneration)loading.value=false}}
function changeScope(){scope.value=scopeType.value==='office'?'office':storeId.value?`store:${storeId.value}`:'';load()}
function changeWeek(){pickedDate.value=monday(pickedDate.value);load()}
function moveWeek(days){pickedDate.value=add(pickedDate.value,days);load()}
function thisWeek(){pickedDate.value=monday(context.value.today);load()}
function optionDisabled(option){return !selectedDay.value?.can_edit || scope.value==='office' && (option.value==='work' && selectedDay.value.office_type!=='work' || option.value==='rest' && !['rest','holiday'].includes(selectedDay.value.office_type))}
function selectShift(option){if(optionDisabled(option))return;dayForm.type=option.value;dayError.value=''}
function openDay(person,day){dayError.value='';selectedPerson.value=person;selectedDay.value=day;Object.assign(dayForm,{type:day.type==='holiday'?'rest':day.type==='overtime'?'work':day.type,reason:day.reason || ''});dayVisible.value=true}
function applyDay(){if(!selectedDay.value?.can_edit)return;if(!shiftOptions.some(option=>option.value===dayForm.type)){ElMessage.warning('请选择排班安排');return}if(dayForm.type==='leave' && !dayForm.reason?.trim()){dayError.value='请填写请假原因';return}Object.assign(selectedDay.value,{type:scope.value==='office' && dayForm.type==='rest' && selectedDay.value.office_type==='holiday'?'holiday':dayForm.type,reason:dayForm.type==='leave'?dayForm.reason.trim():'',start_time:'',end_time:'',next_day:false});dayVisible.value=false}
async function save(publish){try{const reason=week.value.status==='published' && week.value.can_confirm?'调整周排班':'';if(publish)await ElMessageBox.confirm('提交后正式员工本周排班固定，后续调整需由人事处理。','提交周排班');saving.value=true;week.value=(await saveRosterWeek({scope:scope.value,week_start:week.value.week_start,version:week.value.version,employees:week.value.employees,publish,reason})).week;baseline.value=planSnapshot();ElMessage.success('排班已保存')}catch(error){if(error!=='cancel' && error!=='close')ElMessage.error(error.message)}finally{saving.value=false}}
async function openBalance(person){balanceVisible.value=true;balancePerson.value=person;account.value=null;balanceError.value='';balanceLoading.value=true;const generation=++balanceGeneration;try{const result=await getRosterBalance(person.employee_id);if(generation===balanceGeneration){account.value=result.account;revisions.value=result.revisions}}catch(error){if(generation===balanceGeneration)balanceError.value=error.message}finally{if(generation===balanceGeneration)balanceLoading.value=false}}
onMounted(async()=>{loading.value=true;try{context.value=await getRosterContext();pickedDate.value=monday(context.value.today);scope.value=context.value.scopes[0]?.value || '';scopeType.value=scope.value==='office'?'office':'store';storeId.value=scope.value.startsWith('store:')?Number(scope.value.split(':')[1]):null;await load()}catch(error){ElMessage.error(error.message)}finally{loading.value=false}})
</script>
<style scoped>
